const body = $json.body ?? $json;
const textPrompt = String(body.text_prompt ?? body.prompt ?? '').trim();
const negativePrompt = String(body.negative_prompt ?? '').trim();
const audioUrl = String(body.audio_url ?? '').trim();
const durationSeconds = Number(body.duration_seconds ?? body.duration ?? 5);
const width = Number(body.width ?? 1024);
const height = Number(body.height ?? 1024);
const fps = 50;

if (!textPrompt) {
  throw new Error('text_prompt is required');
}
if (!Number.isFinite(durationSeconds) || durationSeconds < 5 || durationSeconds > 1800) {
  throw new Error('duration_seconds must be between 5 and 1800 seconds (5 sec to 30 min)');
}
if (!audioUrl) {
  throw new Error('audio_url is required');
}

const totalFrames = Math.round(durationSeconds * fps);
const jobId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const frames = [];

for (let i = 0; i < totalFrames; i++) {
  const t = Number((i / fps).toFixed(3));
  const prompt = `${textPrompt}. cinematic consistency, frame ${i + 1} of ${totalFrames}, timestamp ${t}s`;
  frames.push({
    frame_index: i,
    timestamp_seconds: t,
    schema: {
      type: 'video_frame_prompt_v1',
      job_id: jobId,
      frame_index: i,
      timestamp_seconds: t,
      prompt,
      negative_prompt: negativePrompt,
      image: { width, height },
      video: { fps, duration_seconds: durationSeconds }
    }
  });
}

return [{
  json: {
    jobId,
    fps,
    durationSeconds,
    totalFrames,
    width,
    height,
    audioUrl,
    webhookUrl: 'https://ppbprahann.app.n8n.cloud/webhook/e665ed44-516c-45a2-afe6-c291e2d7f02a',
    frames
  }
}];

const root = items[0].json;
return root.frames.map((frame) => ({
  json: {
    jobId: root.jobId,
    fps: root.fps,
    durationSeconds: root.durationSeconds,
    totalFrames: root.totalFrames,
    audioUrl: root.audioUrl,
    frame
  }
}));

const incoming = $json;
const imageUrl = incoming.image_url ?? incoming.url ?? incoming.output_url ?? incoming.data?.image_url ?? incoming.data?.url;
if (!imageUrl) {
  throw new Error('Image webhook response missing image_url/url/output_url');
}

const src = $item(0).$node['Explode Frames'].json;
return [{
  json: {
    jobId: src.jobId,
    fps: src.fps,
    durationSeconds: src.durationSeconds,
    totalFrames: src.totalFrames,
    audioUrl: src.audioUrl,
    frame_index: src.frame.frame_index,
    image_url: imageUrl
  }
}];

const all = items.map((i) => i.json).sort((a, b) => a.frame_index - b.frame_index);
if (!all.length) throw new Error('No generated frames found');
const first = all[0];
const payload = {
  jobId: first.jobId,
  fps: first.fps,
  durationSeconds: first.durationSeconds,
  totalFrames: first.totalFrames,
  audioUrl: first.audioUrl,
  frames: all.map((x) => ({ frame_index: x.frame_index, image_url: x.image_url }))
};
const manifestBase64 = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
return [{ json: { ...payload, manifestBase64 } }];
